#!/usr/bin/env python3
"""Generate Lambda operator data from the repository's pinned WPT checkout."""
from pathlib import Path
import hashlib
import json
import subprocess

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / "ref/wpt/mathml/support/operator-dictionary.json"
raw = SOURCE.read_bytes()
entries = json.loads(raw)["dictionary"]
commit = subprocess.check_output(
    ["git", "-C", str(ROOT / "ref/wpt"), "rev-parse", "HEAD"], text=True
).strip()
lines = [
    "// Generated by utils/generate_mathml_operators.py; do not edit.",
    "// Core §3.2.4.2 / Appendix B (D7.2.8).",
    f"// WPT mathml/support/operator-dictionary.json at {commit}.",
    f"// Input SHA-256: {hashlib.sha256(raw).hexdigest()}",
    "// Copyright web-platform-tests contributors; see LICENSE.WPT.",
    "let entries = {",
]
for key, fields in sorted(entries.items()):
    value = ",".join(f"{name}:" + json.dumps(item) for name, item in fields.items())
    # Static symbol labels let the compiler build one packed dictionary shape.
    label = "'" + key.replace("\\", "\\\\").replace("'", "\\'") + "'"
    lines.append("    " + label + ":{" + value + "},")
lines[-1] = lines[-1].removesuffix(",")
lines.extend([
    "}", "",
    "pub fn lookup(text, form, explicit = false) {",
    '    let exact=entries[text++" "++form];',
    '    exact or (if (explicit) null else entries[text++" infix"] or entries[text++" postfix"] or entries[text++" prefix"]) or {}',
    "}", "",
])
(ROOT / "lmd/package/doc/math/mathml_operators.ls").write_text("\n".join(lines))
(ROOT / "lmd/package/doc/math/LICENSE.WPT").write_bytes((ROOT / "ref/wpt/LICENSE.md").read_bytes())
